const withoutCardAt = (army: Card[], index: number): Card[] => [
  ...army.slice(0, index),
  ...army.slice(index + 1),
];

// A Sphinx scores its own point, then variety points for the types it sees
// alongside it — its own card set aside so it is not counted twice.
const scoreSphinxAt = (army: Card[], index: number): number =>
  SPHINX_POINT + scoreTypeVariety(countDistinctTypes(withoutCardAt(army, index)));

export const scoreArmy = (army: Card[]): number =>
  army.reduce(
    (total, card, index) =>
      isSphinx(card) ? total + scoreSphinxAt(army, index) : total,
    0,
  );
